import { estimateFps, findGpuById, findCpuById, defaultVramForGpu } from "./fps-engine.js";
import { estimateVramNeeded } from "./vram-engine.js";
export const DRIVE_META = {
  nvme: { label: "NVMe SSD", mult: 1 },
  ssd: { label: "SATA SSD", mult: 0.9 },
  hdd: { label: "HDD (mechanisch)", mult: 0.35 }
};
export const GRADE_THRESHOLDS = [
  { grade: "S", min: 92, label: "Am Launch-Tag fehlerfrei" },
  { grade: "A", min: 82, label: "Ultra-bereit" },
  { grade: "B", min: 70, label: "Komfortabel bereit" },
  { grade: "C", min: 55, label: "Spielbar, Tweaks planen" },
  { grade: "D", min: 40, label: "Unter Spec, zuerst upgraden" },
  { grade: "F", min: 0, label: "Nicht bereit" }
];
export const WEIGHTS = {
  performance: 0.55,
  vram: 0.2,
  storage: 0.15,
  network: 0.1
};
const clamp = (n, lo = 0, hi = 100) => Math.max(lo, Math.min(hi, n));
const round = (n) => Math.round(n);
// AUDIT FIX H2 (2026-11-17): one install-size constant, 150 GB base, shared
// with the download-time calculator, storage planner and registry copy.
// The old 100 GB anchor awarded full storage marks for 100 GB free while the
// storage planner told the same user to keep 200-235 GB free.
export const REFERENCE_INSTALL_GB = 150;
export const REFERENCE_MBPS = 111;
export function performanceScore(input) {
  const res = input.res ?? "1080p";
  const preset = input.preset ?? "high";
  const cardVramGB = input.cardVramGB ?? defaultVramForGpu(input.gpu.id);
  const r = estimateFps({
    gpu: input.gpu,
    cpu: input.cpu,
    ram: input.ram,
    res,
    preset,
    upscaler: "off",
    frameGen: "off",
    targetFps: 60,
    cardVramGB
  });
  const score = clamp(r.avgFps / 60 * 100);
  return {
    score,
    detail: `${r.avgFps} fps im Schnitt · ${r.lowFps} 1 %-Low bei ${res} Hoch nativ.`,
    metric: `${r.avgFps} fps`
  };
}
export function vramScore(input) {
  const res = input.res ?? "1080p";
  const preset = input.preset ?? "high";
  const vramRes = res === "4K" ? "4K" : res === "1080p" ? "1080p" : "1440p";
  const vramPreset = preset === "very-high" ? "very-high" : preset === "ultra" ? "ultra" : preset;
  const need = estimateVramNeeded(vramRes, vramPreset, {
    rayTracing: false,
    frameGen: false,
    hdTextures: false
  });
  const cardVramGB = input.cardVramGB ?? defaultVramForGpu(input.gpu.id);
  const ratio = cardVramGB / need.totalGB;
  const score = clamp((ratio - 0.5) / (1.15 - 0.5) * 100);
  const short = Math.max(0, +(need.totalGB - cardVramGB).toFixed(1));
  const detail = short > 0 ? `${cardVramGB}-GB-Karte, braucht ${need.totalGB} GB, ${short} GB zu wenig.` : `${cardVramGB}-GB-Karte reicht für den geschätzten Bedarf von ${need.totalGB} GB.`;
  return { score, detail, metric: `${cardVramGB} / ${need.totalGB} GB` };
}
export function storageScore(input) {
  const drive = DRIVE_META[input.driveType];
  const ratio = input.freeStorageGB / REFERENCE_INSTALL_GB;
  const raw = clamp(ratio * 100) * drive.mult;
  const score = clamp(raw);
  const detail = input.driveType === "hdd" ? `${input.freeStorageGB} GB frei auf einer HDD, moderne Open Worlds streamen von SSD; erwarte Pop-in.` : `${input.freeStorageGB} GB frei auf ${drive.label}. Ziel: ${REFERENCE_INSTALL_GB} GB.`;
  return { score, detail, metric: `${input.freeStorageGB} GB` };
}
export function networkScore(input) {
  const mbps = Math.max(0, input.internetMbps);
  const score = clamp(mbps / REFERENCE_MBPS * 100);
  // AUDIT FIX (2026-11-17): the source formula multiplied GB by 8, not 8000,
  // so it understated install time by 1000x (it printed "~0 min" for a
  // 150 GB install at 150 Mbps). 150 GB at 111 Mbps is about 3.0 h.
  const hours = mbps > 0 ? REFERENCE_INSTALL_GB * 8000 / mbps / 3600 : 1 / 0;
  const hoursLabel = !isFinite(hours) || hours > 99 ? "sehr lange" : hours >= 1 ? `${hours.toFixed(1)} Std.` : `${Math.round(hours * 60)} Min.`;
  return {
    score,
    detail: `${mbps} Mbps down, installiert ${REFERENCE_INSTALL_GB} GB in ~${hoursLabel}.`,
    metric: `${mbps} Mbps`
  };
}
export function gradeFor(score) {
  for (const t of GRADE_THRESHOLDS) {
    if (score >= t.min)
      return { grade: t.grade, label: t.label };
  }
  return { grade: "F", label: "Not ready" };
}
export function estimateReadiness(input) {
  const performance = performanceScore(input);
  const vram = vramScore(input);
  const storage = storageScore(input);
  const network = networkScore(input);
  const weighted = performance.score * WEIGHTS.performance + vram.score * WEIGHTS.vram + storage.score * WEIGHTS.storage + network.score * WEIGHTS.network;
  const score = round(weighted);
  const { grade, label } = gradeFor(score);
  const pairs = [
    ["performance", performance.score],
    ["vram", vram.score],
    ["storage", storage.score],
    ["network", network.score]
  ];
  const weakest = pairs.reduce((a, b) => b[1] < a[1] ? b : a)[0];
  const verdictMap = {
    S: "Alles reicht mit Reserve. Du wirst am Launch-Tag mit Max-Einstellungen spielen.",
    A: "Heute bereit, du wirst am Launch-Tag nur ein oder zwei Einstellungen tweaken.",
    B: "Bereit. Ein Sub-Score liegt zurück, aber nichts blockiert einen reibungslosen Launch.",
    C: "Spielbar, aber wähle eine Auflösungs-/Preset-Leiter, die zu deinem schwächsten Glied passt.",
    D: "Unter der praktischen Untergrenze. Fixe deinen schwächsten Score vor dem Pre-Load.",
    F: "Nicht bereit. Du wirst keinen reibungslosen Launch haben, bis du upgradest."
  };
  return {
    score,
    grade,
    gradeLabel: label,
    performance,
    vram,
    storage,
    network,
    verdict: verdictMap[grade],
    weakest
  };
}

